def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_m = me[-1]
    last_o = opp[-1]
    oppD = opp.count('D')
    recent10 = opp[-10:] if n >= 10 else opp
    recent10D = recent10.count('D')

    if n >= 15 and oppD * 5 > n * 3 and recent10D >= 6:
        return 'D'

    if last_m == 'D' and last_o == 'D':
        run = 0
        i = n - 1
        while i >= 0 and me[i] == 'D' and opp[i] == 'D':
            run += 1
            i -= 1
        recent6 = opp[-6:] if n >= 6 else opp
        recent6D = recent6.count('D')
        if run >= 2 and oppD * 2 < n and recent6D <= 4:
            if run < 6 or rng.random() < 0.2:
                return 'C'
        return 'D'

    if n >= 2 and opp[-2] == 'D' and last_o == 'D':
        return 'D'

    if last_o == 'C':
        return 'C'

    if oppD == 1 and n < 98:
        return 'C'

    if n >= 2 and me[-2] == 'D' and opp[-2] == 'C':
        cycles = 0
        i = n - 1
        start = max(1, n - 12)
        while i >= start:
            if me[i] == 'C' and opp[i] == 'D' and i >= 1 and me[i - 1] == 'D' and opp[i - 1] == 'C':
                cycles += 1
                i -= 2
            else:
                i -= 1
        recent6 = opp[-6:] if n >= 6 else opp
        recent6D = recent6.count('D')
        if cycles == 1 and (recent6D <= 3 or n <= 12):
            return 'C'
        if cycles <= 2 and oppD * 2 < n and recent6D <= 4:
            if rng.random() < 0.6:
                return 'C'
        if oppD * 3 < n * 2 and rng.random() < 0.2:
            return 'C'
        return 'D'

    recent6 = opp[-6:] if n >= 6 else opp
    recent6D = recent6.count('D')
    if recent6D <= 1 and oppD * 4 < n and rng.random() < 0.15:
        return 'C'

    return 'D'
